/// Every calculation in the registry, sorted by id.
static ALL_SPECS: &[&CalcSpec] = &[
    &ANTOINE_VAPOR_PRESSURE_SPEC,
    &CHUNG_CONDUCTIVITY_SPEC,
    &CHUNG_VISCOSITY_SPEC,
    &COSTALD_MOLAR_VOLUME_SPEC,
    &HEAT_OF_VAPORIZATION_SPEC,
    &IDEAL_GAS_CP_SPEC,
    &LIQUID_HEAT_CAPACITY_SPEC,
    &PR78_KAPPA_SPEC,
    &PR_ALPHA_AB_SPEC,
    &PR_DEPARTURE_SPEC,
    &PR_KAPPA_SPEC,
    &PR_MASS_DENSITY_SPEC,
    &PR_MOLAR_VOLUME_SPEC,
    &PR_PENELOUX_SHIFT_SPEC,
    &PR_Z_FACTOR_SPEC,
    &PRSV_KAPPA_SPEC,
    &RACHFORD_RICE_BINARY_SPEC,
    &RACKETT_MOLAR_VOLUME_SPEC,
    &RK_ALPHA_AB_SPEC,
    &RK_DEPARTURE_SPEC,
    &SRK_ALPHA_AB_SPEC,
    &SRK_DEPARTURE_SPEC,
    &SRK_KAPPA_SPEC,
    &SRK_PENELOUX_SHIFT_SPEC,
    &SRK_Z_FACTOR_SPEC,
    &TWU_KAPPA_SPEC,
    &TYN_CALUS_DIFFUSIVITY_SPEC,
    &VDW1F_MIX_BINARY_SPEC,
];

/// All specs, in a stable order.
#[must_use]
pub fn specs() -> &'static [&'static CalcSpec] {
    ALL_SPECS
}

/// Look up a spec by id.
#[must_use]
pub fn spec(id: &str) -> Option<&'static CalcSpec> {
    ALL_SPECS.iter().copied().find(|s| s.id == id)
}
